import { withAuth } from "@workos-inc/authkit-nextjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Reads the signed-in user from the WorkOS AuthKit session and syncs it into
// the local user store, so the rest of the app (e.g. the team list in
// listUsers()) keeps working against the same User type as before.
// Returns undefined when nobody is signed in.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  if (!user) return undefined;

  const name =
    [user.firstName, user.lastName].filter(Boolean).join(" ") || user.email;

  const existing = users.find((u) => u.id === user.id);
  if (existing) {
    existing.email = user.email;
    existing.name = name;
    return existing;
  }

  const created: User = {
    id: user.id,
    email: user.email,
    name,
    createdAt: (user.createdAt ?? new Date().toISOString()).slice(0, 10),
  };
  users.push(created);
  return created;
}

