async function refreshSession({ organizationId: nextOrganizationId, ensureSignedIn = false, } = {}) {
    const session = await getSessionFromCookie();
    if (!session) {
        if (ensureSignedIn) {
            await redirectToSignIn();
        }
        return { user: null };
    }
    const { org_id: organizationIdFromAccessToken } = decodeJwt(session.accessToken);
    let refreshResult;
    try {
        refreshResult = await getWorkOS().userManagement.authenticateWithRefreshToken({
            clientId: WORKOS_CLIENT_ID,
            refreshToken: session.refreshToken,
            organizationId: nextOrganizationId ?? organizationIdFromAccessToken,
        });
    }
    catch (error) {
        throw new TokenRefreshError(`Failed to refresh session: ${error instanceof Error ? error.message : String(error)}`, error, { ...getSessionErrorContext(session), isTransient: isTransientRefreshError(error) });
    }
    const headersList = await headers();
    const url = headersList.get('x-url');
    await saveSession(refreshResult, url || WORKOS_REDIRECT_URI);
    const { accessToken, user, impersonator } = refreshResult;
    const { sid: sessionId, org_id: organizationId, role, roles, permissions, entitlements, feature_flags: featureFlags, } = decodeJwt(accessToken);
    return {
        sessionId,
        user,
        organizationId,
        role,
        roles,
        permissions,
        entitlements,
